// Runtime corpus access. Production serves exclusively from the pre-serialised
// posts-cache.json (generated by scripts/generate-posts-cache.ts at prebuild);
// the full raw-source parse lives in parse-raw-sources.ts and is loaded only
// outside production, behind the NODE_ENV guard below. That guard is
// load-bearing for bundle size: the bundler drops the dead branch in production
// builds, so output file tracing never sees the raw-source fs reads and the
// ~36 MB of source dumps stay out of every serverless function.

import fs from 'fs';
import path from 'path';
import { Post, HIDDEN_SOURCES } from './types';

// Module-level cache — populated on first call and reused for the lifetime
// of the Node.js process. JSON.parse of the prebuilt cache is ~50x faster than
// the custom parsing logic, cutting cold-start time from ~5 s to <200 ms.
let _postsCache: Post[] | null = null;

export function getAllPosts(): Post[] {
  if (_postsCache) return _postsCache;

  const cachePath = path.join(process.cwd(), 'src', 'data', 'posts-cache.json');
  if (fs.existsSync(cachePath)) {
    try {
      _postsCache = JSON.parse(fs.readFileSync(cachePath, 'utf-8')) as Post[];
      return _postsCache;
    } catch {
      // Corrupt cache — fall through
    }
  }

  if (process.env.NODE_ENV !== 'production') {
    // Dev / scripts fallback: parse the raw source dumps. A require (not a
    // top-level import) inside this guarded branch, so production bundles —
    // where the branch is statically dead — exclude the module entirely.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { parseAllContent } = require('./parse-raw-sources') as typeof import('./parse-raw-sources');
    _postsCache = parseAllContent();
    return _postsCache;
  }

  throw new Error(
    'posts-cache.json is missing or corrupt — the production build must run ' +
    'scripts/generate-posts-cache.ts (npm prebuild) before next build.'
  );
}

export function getPostBySlug(slug: string): Post | undefined {
  const posts = getAllPosts();
  return posts.find((p) => p.slug === slug);
}

/**
 * Returns all posts EXCEPT those from hidden sources (chronicle, etc.).
 * Use this for search, browse, related posts, and any public-facing feature.
 * Use getAllPosts() only when you intentionally need hidden content (e.g. /downloads).
 */
export function getPublicPosts(): Post[] {
  return getAllPosts().filter((p) => !HIDDEN_SOURCES.includes(p.source));
}
